	private static final class CountingSource implements NativeLmdbQuerySource {
		final int[][] opens = new int[2][2], reads = new int[2][2];
		int closed;

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public long idOf(Value value) {
			String prefix = "urn:factorized-refusal:";
			return value.stringValue().startsWith(prefix)
					? Long.parseLong(value.stringValue().substring(prefix.length()))
					: UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return value(id);
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return coveringProfile(ENUM_ROWS + COUNT_ROWS);
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return OptionalDouble.of(bySubject ? fanout(predicate) : 1D);
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			return OptionalDouble.of(bySubject ? 1D : fanout(predicate));
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return OptionalLong.of(bySubject ? 1L : fanout(predicate));
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long c) {
			return iterator(s, p, o, c, 1);
		}

		@Override
		public NativeProbe newProbe() {
			return new NativeProbe() {
				RecordIterator current;

				@Override
				public RecordIterator open(long s, long p, long o, long c) {
					if (current != null) {
						current.close();
					}
					current = iterator(s, p, o, c, 0);
					return current;
				}

				@Override
				public void close() {
					if (current != null) {
						current.close();
						current = null;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long c) {
			if ((s != UNKNOWN_ID && s != KEY) || (c != UNKNOWN_ID && c != 0L)) {
				return 0L;
			}
			if (o == UNKNOWN_ID) {
				return fanout(p);
			}
			long start = p == ENUM ? 1_001L : 2_001L;
			return o >= start && o < start + fanout(p) ? 1L : 0L;
		}

		@Override
		public boolean has(long s, long p, long o, long c) {
			return count(s, p, o, c) > 0L;
		}

		@Override
		public double estimate(long s, long p, long o, long c) {
			return count(s, p, o, c);
		}

		private int fanout(long predicate) {
			return predicate == ENUM ? ENUM_ROWS : predicate == COUNT ? COUNT_ROWS : 0;
		}

		private RecordIterator iterator(long s, long p, long o, long c, int kind) {
			int branch = p == ENUM ? 0 : 1;
			opens[kind][branch]++;
			return new RecordIterator() {
				int at;
				boolean done;

				@Override
				public long[] next() {
					if (done) {
						return null;
					}
					while (at < fanout(p)) {
						long value = (p == ENUM ? 1_001L : 2_001L) + at++;
						if ((s == UNKNOWN_ID || s == KEY) && (o == UNKNOWN_ID || o == value)
								&& (c == UNKNOWN_ID || c == 0L)) {
							reads[kind][branch]++;
							return new long[] { KEY, p, value, 0L };
						}
					}
					return null;
				}

				@Override
				public void close() {
					if (!done) {
						done = true;
						closed++;
					}
				}
			};
		}

		Measured snapshot(Map<Value, Long> bag, LmdbNativeDecisionTestAccess.Captured quote) {
			return new Measured(bag, opens[0][0], opens[0][1], opens[1][0], opens[1][1],
					reads[0][0], reads[0][1], reads[1][0], reads[1][1], closed, quote);
		}
	}
